 box(x,y,z,w,d,h,color,edge='#45626c'){if(this.plan){this.path([[x,y],[x+w,y],[x+w,y+d],[x,y+d]].map(p=>this.point(...p,z)),color,edge,.7);return}const p=(a,b,k)=>this.point(a,b,k);this.path([p(x,y+d,z),p(x+w,y+d,z),p(x+w,y+d,z+h),p(x,y+d,z+h)],this.shade(color,.62),edge,.65);this.path([p(x+w,y,z),p(x+w,y+d,z),p(x+w,y+d,z+h),p(x+w,y,z+h)],this.shade(color,.78),edge,.65);this.path([p(x,y,z+h),p(x+w,y,z+h),p(x+w,y+d,z+h),p(x,y+d,z+h)],color,edge,.65)}
